  "evaldesk.emptyRuns": {"zh": "还没有评测记录。满足条件的实验启动后会出现在这里。", "en": "No evaluations yet. Admitted experiments will appear here after starting.", "ja": "評価履歴はありません。開始した実験がここに表示されます。"},
  "evaldesk.result": {"zh": "结果与有效性", "en": "Result and validity", "ja": "結果と有効性"},
  "evaldesk.selectRun": {"zh": "选择一条记录查看结果和原因。", "en": "Select a run to inspect its result and reason.", "ja": "実行を選択して結果と理由を確認してください。"},
  "evaldesk.coverage": {"zh": "规则匹配覆盖", "en": "Rule-match coverage", "ja": "ルール一致カバレッジ"},
  "evaldesk.cases": {"zh": "条用例", "en": "cases", "ja": "ケース"},
  "evaldesk.cost": {"zh": "B − A：调用 {calls} 次，token {tokens}", "en": "B − A: {calls} calls, {tokens} tokens", "ja": "B − A：呼出 {calls} 回、{tokens} トークン"},
  "evaldesk.costUnknown": {"zh": "成本数据不完整，无法比较。", "en": "Cost data is incomplete; no cost comparison.", "ja": "コストデータが不完全なため比較できません。"},
  "evaldesk.noWinner": {"zh": "这是单次开发集诊断，覆盖差异不能证明版本胜出。正式选版仍需独立任务、重复运行、留出验证和人工审核。", "en": "This is one development-set diagnostic. Coverage differences do not establish a winner. Release decisions need independent tasks, repeats, held-out validation and human review.", "ja": "単回の開発セット診断です。正式な選定には独立タスク、反復、留保検証、人による確認が必要です。"},
  "evaldesk.mutation": {"zh": "变异检出", "en": "Mutation detection", "ja": "変異検出"},
