  "evaldesk.legacy": {"zh": "此记录缺少新版有效性证据，仅供历史参考。", "en": "This record lacks current validity evidence and is historical only.", "ja": "この記録には新しい有効性証拠がなく、履歴参照用です。"},
  "evaldesk.status.running": {"zh": "运行中", "en": "Running", "ja": "実行中"},
