  "evaldesk.status.legacy": {"zh": "历史结果", "en": "Historical result", "ja": "過去の結果"},
  "evaldesk.reason.eval_runtime_unsupported": {"zh": "此入口不能切换 Claude/Penguin 宿主。请使用支持该宿主的实验适配器；不会退回 graph 冒充对比。", "en": "This executor cannot switch native hosts. Use a host-capable experiment adapter; no silent graph fallback.", "ja": "この実行方式は宿主切替に未対応です。対応アダプターが必要です。"},
  "evaldesk.reason.eval_graph_missing": {"zh": "找不到指定流程或版本，请修正实验定义。", "en": "Workflow or version is missing. Correct the definition.", "ja": "フローまたはバージョンがありません。定義を修正してください。"},
  "evaldesk.reason.eval_cases_node_missing": {"zh": "评分节点不在所选流程中，请指定产出 cases 的节点。", "en": "Scoring node is missing. Select a node that produces cases.", "ja": "採点ノードがありません。cases を出力するノードを指定してください。"},
  "evaldesk.reason.eval_gold_unavailable": {"zh": "数据文件不存在或格式无效。请提供明确的数据路径与有效条目，不会使用其他数据集替代。", "en": "Dataset is missing or invalid. Supply an explicit valid dataset; no fallback will be used.", "ja": "データがないか無効です。有効なパスと項目を指定してください。"},
  "evaldesk.reason.eval_request_invalid": {"zh": "定义不完整或参数不合法。请检查流程、数据路径与两组配置。", "en": "Definition or parameters are invalid. Check workflow, dataset path and both arms.", "ja": "定義が不完全です。フロー、データパス、両群の設定を確認してください。"},
  "evaldesk.reason.eval_ablation_unknown": {"zh": "定义包含不支持的消融开关，请修正。", "en": "Unknown ablation switch. Correct the definition.", "ja": "未対応のアブレーション設定です。"},
  "evaldesk.reason.eval_development_items_missing": {"zh": "没有可用于开发诊断的条目，留出条目不会在此展示。", "en": "No development items. Held-out items are not exposed here.", "ja": "開発用の項目がありません。留保項目は公開しません。"},
  "evaldesk.reason.eval_run_not_completed": {"zh": "一组运行未正常完成，未生成有效对比。请检查关联运行。", "en": "An arm did not complete. No valid comparison was produced; inspect its run.", "ja": "片方の実行が未完了です。有効な比較はありません。"},
  "evaldesk.reason.eval_output_missing": {"zh": "运行没有有效用例产物，不能按零覆盖评分。", "en": "Run has no case output; it cannot be scored as zero coverage.", "ja": "ケース出力がなく、ゼロ点として採点できません。"},
  "evaldesk.reason.eval_prompt_drift": {"zh": "两组运行之间指令发生变化，结果不可比较。", "en": "Instructions changed between arms; results are not comparable.", "ja": "両群の間で指示が変化したため比較できません。"},
  "evaldesk.reason.eval_timeout": {"zh": "等待运行超时，已请求停止关联运行。", "en": "Run timed out; cancellation was requested.", "ja": "タイムアウトしました。実行停止を要求しました。"},
