  "bench.rerunNode": {zh:"从此节点重跑",en:"Rerun from this node",ja:"このノードから再実行"},
  "bench.rerunNodeHint": {zh:"创建新运行，沿用配置与上游产物。仅运行此节点后暂停；旧运行保留，后续产物需重新生成和审核。",en:"Create a new run with the same configuration and upstream artifacts. Pause after this node; keep the original run. Downstream artifacts require regeneration and review.",ja:"設定と上流の成果物を引き継いで新規実行。このノード完了後に停止し、元の実行を保持します。"},
  "bench.rerunStopFirst": {zh:"请先停止当前运行，再从此节点重跑。",en:"Stop the current run before restarting from this node.",ja:"現在の実行を停止してから再実行してください。"},
