  "bench.exploreWallet": {"zh": "带钱包探索", "en": "Explore with a wallet", "ja": "Explore with a wallet"},
  "bench.exploreWalletHint": { zh: "注入本机钱包（与执行用例同一个账户）。只对连上钱包才看得到完整界面的产品有用；默认值来自环境设置。", en: "Injects this machine’s wallet (the same account used to run cases). Only useful for products that show their full UI after a wallet connects; defaults to the environment setting.", ja: "ウォレットを注入します。" },
  "bench.exploreInteract": {"zh": "允许点会改状态的东西", "en": "Allow state-changing clicks", "ja": "Allow state-changing clicks"},
  "bench.exploreInteractHint": { zh: "放开会改变状态的目标（提交、删除、确认这类）。不放开时它们一律记 policy:side_effect，永远不点。", en: "Unblocks targets that change state (submit, delete, confirm). Otherwise they are always recorded as policy:side_effect and never clicked.", ja: "状態を変えるターゲットを許可します。" },
  "bench.exploreInteractWarn": {"zh": "只有这次用的环境勾过「允许不可逆操作」、且探索地址就是那个环境的地址才允许；否则服务端会拒绝这次创建（403）。在「被测对象」的环境设置里勾。", "en": "Only allowed when the environment for this run has “allow irreversible steps” ticked and the explore URL is that environment’s address; otherwise the server refuses to create this run (403). Tick it in the target’s environment settings.", "ja": "Only allowed when this run’s environment allows irreversible steps."},
  "bench.modulePlan": {"zh": "模块树提案", "en": "Module plan", "ja": "Module plan"},
  "bench.moduleReviewTitle": {"zh": "产品模块规划审核", "en": "Review product module plan", "ja": "製品モジュール計画のレビュー"},
  "bench.moduleReviewSubmitting": {"zh": "正在提交审核…", "en": "Submitting approval…", "ja": "承認を送信中…"},
  "bench.freezeModules": {"zh": "审核通过", "en": "Approve", "ja": "承認する"},
  "bench.freezeModulesHint": {"zh": "请查看产品模块规划，确认模块划分与范围。审核通过后将锁定模块结构，用户故事会按此拆分；随后点击“执行下一节点”继续。", "en": "Review the module structure and scope. Approval locks the structure for user story generation. Then select “Run next node” to continue.", "ja": "モジュール構成と範囲を確認してください。承認後は構成が固定されます。「次のノードを実行」で続行できます。"},
  "bench.modulesFrozen": {"zh": "审核已通过，模块结构已锁定。用户故事将按此拆分；如需修改，可从产品模块规划节点重跑。", "en": "Approved. The module structure is locked for user story generation. To change it, rerun from the product module planning node.", "ja": "承認済み。モジュール構成は固定されています。変更する場合はモジュール計画ノードから再実行してください。"},
  "bench.modulePlanFrozen": {"zh": "审核已通过：后续节点按此模块结构处理", "en": "Approved: subsequent nodes use this module structure", "ja": "承認済み：後続ノードはこの構成を使用します"},
  "bench.modulePlanFindings": {"zh": "机检", "en": "Machine checks", "ja": "Machine checks"},
  "bench.modulePlanClean": {"zh": "机检没有发现问题。「这棵树切得对不对」仍然要人看。", "en": "No machine findings. Whether the tree is cut right still needs a human.", "ja": "No machine findings."},
  "bench.outOfScope": {"zh": "声明不在范围内的材料段", "en": "Sections declared out of scope", "ja": "Sections declared out of scope"},

  "bench.title": {"zh": "工作台", "en": "Workbench", "ja": "Workbench"},
