  "modelRoles.fromEnv": { zh: "当前使用 .env。修改后保存会覆盖当前项目；只改 env 时，重启服务后生效。", en: "Using .env. Saving creates a project override. Restart the server after editing env.", ja: ".env を使用中。保存でプロジェクト設定に上書きします。env 変更後はサーバーを再起動してください。" },
  "modelRoles.title": { zh: "规划与执行模型", en: "Planning & execution models", ja: "計画・実行モデル" },
