  "modelRoles.executorHelp": { zh: "低成本视觉模型，负责页面感知、定位和动作执行。", en: "A low-cost vision model for page perception, targeting and actions.", ja: "画面認識、要素特定、操作を行う低コスト視覚モデル。" },
