  "modelRoles.keySaved": { zh: "已有加密密钥；留空保留，输入新值替换。", en: "Encrypted key saved. Leave blank to keep it, or enter a replacement.", ja: "暗号化キー保存済み。空欄で保持、新しい値で置換します。" },
