  "modelRoles.probeHelp": { zh: "测试会调用对应模型并可能产生费用。执行角色发送图片请求；成功只代表端点接受请求，不代表定位精度或领域质量已验证。", en: "Testing calls the selected model and may incur a cost. Execution sends an image request; success does not establish targeting accuracy or domain quality.", ja: "テストは対応モデルを呼び出し、料金が発生する場合があります。実行モデルには画像を送信します。成功は位置精度や専門品質の保証ではありません。" },
  "modelRoles.unconfigured": { zh: "未配置", en: "Not configured", ja: "未設定" },
