  "modelRoles.inherited": { zh: "规划模型由 Claude Code / Codex / PenguinHarness 宿主提供。这里只需配置 Midscene 执行角色。", en: "Claude Code, Codex or PenguinHarness supplies the planner. Configure only the Midscene executor here.", ja: "計画は Claude Code / Codex / PenguinHarness が提供。ここでは Midscene 実行モデルのみ設定します。" },
  "modelRoles.migration": { zh: "检测到旧版共用模型配置。请明确填写两个角色；系统不会自动把执行模型当作规划模型。", en: "Legacy shared model settings detected. Choose each role explicitly before using the new configuration.", ja: "旧共通設定を検出しました。新設定では各役割を明示的に指定してください。" },
  "modelRoles.loading": { zh: "读取项目模型配置…", en: "Loading project models…", ja: "プロジェクト設定を読み込み中…" },
  "modelRoles.reload": { zh: "重新读取", en: "Reload", ja: "再読み込み" },
  "modelRoles.error.generic": { zh: "配置操作失败，请检查服务连接后重新读取。", en: "Configuration request failed. Check the server and reload.", ja: "設定操作に失敗。サーバー接続を確認して再読み込みしてください。" },
  "modelRoles.error.profile_version_conflict": { zh: "配置已被另一处更新，请重新读取后修改。", en: "Configuration changed elsewhere. Reload before editing.", ja: "設定が別の場所で更新されました。再読み込みしてください。" },
  "modelRoles.error.endpoint_change_requires_credential_choice": { zh: "更换地址时请重新输入密钥，或明确清除密钥。", en: "When changing the endpoint, enter a key or explicitly remove it.", ja: "接続先の変更時はキーを再入力するか、明示的に削除してください。" },
