  "modelRoles.error.invalid_profile": { zh: "请检查配置字段；地址不能包含密钥、查询参数或片段。", en: "Check the fields. The endpoint cannot contain credentials, query parameters or fragments.", ja: "設定を確認してください。URL に認証情報、クエリ、フラグメントは使えません。" },
