  "runs.decidedByWhy.machine": {
    zh: "这次运行的每一条断言都由程序判定——快，且重跑结果一样",
    en: "every assertion in this run was settled by a program — fast, and the same on a re-run",
    ja: "この実行の全検証をプログラムが判定——高速で再実行しても同じ結果",
  },
  "runs.decidedByWhy.judge": {
    zh: "至少有一条断言是模型看截图判的：慢，且同一次重跑可能给出不同结论",
    en: "at least one assertion was judged by a model from a screenshot: slow, and a re-run can disagree with itself",
    ja: "少なくとも一つの検証はモデルが画面から判定：低速で、再実行時に結論が変わりうる",
  },
  "runs.retriedWhy": {
    zh: "重试过——一次要靠重试才绿的通过，值得少信一点",
    en: "it was retried — a pass that needed a retry is worth less than one that did not",
    ja: "リトライあり——再試行で初めて成功した合格は、その分だけ信頼度が下がります",
  },
  "runs.noShots": {
    zh: "这次运行没有留下截图",
    en: "this run left no screenshots",
    ja: "この実行はスクリーンショットを残していない",
  },
  "runs.noShotsWorkflow": {
    zh: "这条执行记录里没有截图。它多半跑在「工作流执行把截图路径记下来」这个改动之前——那之前执行器虽然落了盘，产物类型里却没有承载它的字段，记录时只能存一个空数组。重跑一次就有了",
    en: "this execution has no screenshots. It most likely ran before workflow executions started recording screenshot paths — until then the executor wrote them to disk but the outcome type had no field to carry them. Re-run the case and they will be there",
    ja: "この実行にスクリーンショットはありません。ワークフロー実行がパスを記録するようになる前の実行と思われます——それ以前は実行器が保存しても成果物の型に該当フィールドがなく、空配列として記録されていました。再実行すれば取得されます",
  },
  "runs.backToList": { zh: "返回列表", en: "back to list", ja: "一覧に戻る" },
  "runs.searchPlaceholder": {
    zh: "搜用例名 / 失败原因…",
    en: "search case or failure…",
    ja: "ケース名・失敗理由を検索…",
  },
  "runs.attemptsN": { zh: "{n} 轮", en: "{n} attempts", ja: "{n} 回" },
  "runs.roundN": { zh: "第 {n} 轮", en: "attempt {n}", ja: "第 {n} 回" },
  "runs.attemptsWhy": {
    zh: "同一条用例跑了多次——多半是修复循环改完之后又跑了一遍。主行是最终结论，展开看每一轮",
    en: "the same case ran more than once — usually the repair loop re-running it after a fix. The top row is the final verdict; expand for each attempt",
    ja: "同一ケースが複数回実行——多くは修復ループによる再実行。上段が最終結論、展開で各回を表示",
  },
  "runs.decidedBy.machine": { zh: "程序判定", en: "settled by a program", ja: "プログラム判定" },
