  "wf.capStopped": { zh: "停在上限上", en: "stopped at its cap", ja: "上限で停止" },
  "wf.capTitle": { zh: "这次运行的上限", en: "This run's cap", ja: "この実行の上限" },
  "wf.cap.calls": { zh: "调用次数", en: "calls", ja: "呼び出し回数" },
  "wf.cap.usd": { zh: "金额", en: "spend", ja: "金額" },
  "wf.cap.ms": { zh: "时间", en: "time", ja: "時間" },
  "wf.capHit": { zh: "到顶了", en: "reached", ja: "到達" },
  "wf.capWhy": {
    zh: "上限是硬的：撞上了就停，续跑也不会把它撤掉。所以要继续，得先明确地改上限或撤掉它——让「继续」顺手把上限提上去，等于让上限在最容易被忽略的那一刻失效。",
    en: "The cap is hard: reaching it stops the run, and resuming does not quietly lift it. To continue you must change or clear it deliberately — letting a Continue button raise the cap is letting the cap fail at exactly the moment it matters.",
    ja: "上限は厳格です：到達すれば停止し、再開しても解除されません。続けるには上限を明示的に変更または解除してください——「続行」が上限を引き上げるなら、最も重要な瞬間に上限は機能しません。",
  },
  "wf.capKept": {
    zh: "已经跑出来的产物都还在：改完上限之后是从停住的那一步接着往下走，不是从头再来。花费也接着算——它是整次运行的上限，不是每续一次给一份。",
    en: "Everything already produced is kept: after changing the cap the run continues from where it stopped, not from the beginning. Spend carries over too — the cap is for the whole run, not one per resume.",
    ja: "既存の成果物は保持されます：上限変更後は停止地点から続行し、最初からではありません。消費も引き継がれます——上限は実行全体に対するもので、再開ごとではありません。",
  },
  "wf.capNone": { zh: "不限", en: "none", ja: "無制限" },
  "wf.capBlank": {
    zh: "留空表示这一项不限。三项各自独立，任意一项到顶都会停。",
    en: "Leave blank for no cap on that item. The three are independent; reaching any one stops the run.",
    ja: "空欄はその項目の無制限を意味します。三項目は独立し、いずれかに到達すると停止します。",
  },
  "wf.capApply": { zh: "改上限并继续", en: "Change cap and continue", ja: "上限を変更して続行" },
  "wf.capClear": { zh: "撤掉上限并继续", en: "Clear cap and continue", ja: "上限を解除して続行" },
