  "code.stop.product-defect": { zh: "判定为产品缺陷，拒绝再改", en: "reported as a product defect — refused to keep editing", ja: "製品欠陥と判定し、修正を中止" },
  "base.budgetLine": { zh: "性能预算（毫秒）：", en: "Performance budget (ms):", ja: "パフォーマンス予算（ミリ秒）：" },
  "base.overBudget": { zh: "超预算 {cap}", en: "over budget {cap}", ja: "予算 {cap} 超過" },
  "base.inBudget": { zh: "预算 {cap} 内", en: "within budget {cap}", ja: "予算 {cap} 内" },
  "base.budgetWhy": {
    zh: "基线保「别变得更慢」，预算保「本来就不该这么慢」。只跟基线比会漏掉一种情况：基线本身就慢。",
    en: "The baseline guards against getting slower; the budget guards against being slow in the first place. Comparing only to the baseline misses the case where the baseline is already slow.",
    ja: "ベースラインは「これ以上遅くしない」、予算は「そもそもこんなに遅くない」を守ります。ベースライン比較だけでは、ベースライン自体が遅い場合を見逃します。",
  },
  "trace.noStoriesTitle": { zh: "这个项目还没有故事", en: "No stories in this project yet", ja: "このプロジェクトにはまだストーリーがありません" },
  "trace.noStoriesWhy": {
    zh: "故事是在复核队列里批准用例时一起入库的。批准过之后，这里会长出一棵树：故事 → 用例 → 测试点，一眼看得出哪条需求根本没被测到。",
    en: "Stories are written when cases are approved in the review queue. Once something is approved, this becomes a tree \u2014 story, case, test point \u2014 where a requirement nothing tests stands out at a glance.",
    ja: "ストーリーはレビューキューでケースを承認したときに保存されます。承認後、ここはストーリー → ケース → テスト観点のツリーになり、テストされていない要件が一目で分かります。",
  },
