    en: "a document expresses intent, so a case written against it can fail because the product is wrong. Note: if the graph pins its own paths, the run reads those, not these — you are warned at start",
    ja: "資料は意図を表すため、それに対して書いたケースの失敗は「製品が誤っている」ことを意味しうる。グラフ側でパスが固定されている場合はそちらが読まれます（起動時に警告）",
