  "bench.workUnitsHint": { zh: "服务端按模块子树把故事/用例拆成单元，规划器一次只领一个。不拆的话整份由一次模型调用写完，实测覆盖会卡在一次答复的篇幅上（6 条 vs 拆开后的 34 条）。", en: "The server splits stories/cases into units along the module tree and the planner claims one at a time. Without it the whole bundle comes from a single model call, and coverage is capped by one reply's length (measured: 6 stories vs 34).", ja: "サーバーがモジュール単位に分割し、プランナーは1つずつ取得します。" },
  "bench.planner": {"zh": "规划由谁跑", "en": "Planner", "ja": "プランナー"},
  "bench.plannerDefault": {"zh": "服务端默认", "en": "Server default", "ja": "サーバーの既定"},
  "bench.plannerClaude": {"zh": "Claude Code（本机登录的 Claude）", "en": "Claude Code (the Claude signed in on this machine)", "ja": "Claude Code（このマシンでログインした Claude）"},
  "bench.plannerPenguin": {"zh": "Penguin（实验性，用项目配置的规划模型）", "en": "Penguin (experimental, uses the project's planner model)", "ja": "Penguin（実験的・プロジェクトのプランナーモデル）"},
  "bench.plannerHint": {"zh": "写故事和用例的模型。服务端默认由 TP_AGENT_RUNTIME 决定，不设时是 Claude Code；Penguin 需要 Node 24 与 Penguin 服务。本机起不来的运行时会在创建时被拒绝。", "en": "The model that writes stories and cases. The server default comes from TP_AGENT_RUNTIME (Claude Code when unset); Penguin needs Node 24 and a Penguin server. A runtime that cannot start on this machine is refused when the run is created.", "ja": "ストーリーとケースを書くモデル。既定は TP_AGENT_RUNTIME（未設定なら Claude Code）。"},
  "bench.rulePackVersion": { zh: "规则包版本", en: "Rule pack version", ja: "ルールパックのバージョン" },
  "bench.rulePackLatest": { zh: "用项目当前这一版（推荐）", en: "Use the project's current version (recommended)", ja: "プロジェクトの最新版を使う" },
  "bench.rulePackVersionHint": { zh: "版本在「产品规则包」页里管理。下面那个框只在要临时试一份没入库的包时才用。", en: "Versions are managed on the Product rule packs page. The box below is only for trying a pack that is not stored yet.", ja: "バージョンは「プロダクトルールパック」ページで管理します。" },
  "surface.rulePacks": { zh: "产品规则包", en: "Product rule packs", ja: "プロダクトルールパック" },
  "rulePack.intro": { zh: "规则包是这个项目的领域事实：探索该点哪些目标、前提由谁提供、哪些文案在这个行业里算副作用。它按内容哈希存版本——同样的内容重复上传是同一版，改一个字就是新的一版。新建工作流不显式指定时，用最新的这一版。", en: "A rule pack is this project's domain fact: which targets exploration should activate, which capability comes from where, which labels count as a side effect in this industry. Versions are keyed by content hash — re-uploading the same content is the same version, changing one character makes a new one. A new workflow uses the latest version unless it names one.", ja: "ルールパックはこのプロジェクトのドメイン事実です。" },
  "rulePack.draft": { zh: "聊出一版", en: "Draft one by talking", ja: "会話で作る" },
  "rulePack.upload": { zh: "上传新版（.json）", en: "Upload a version (.json)", ja: "バージョンをアップロード (.json)" },
  "rulePack.empty": { zh: "这个项目还没有规则包。上传一份之后，探索节点才知道该点哪些目标、哪些前提由谁提供。", en: "No rule pack yet. Upload one so exploration knows which targets to activate and where each capability comes from.", ja: "ルールパックがまだありません。" },
  "rulePack.pick": { zh: "选左边一版看它的内容。", en: "Pick a version on the left to see its content.", ja: "左のバージョンを選んでください。" },
  "rulePack.counts": { zh: "模块 {m} · 功能 {f} · 规则 {r} · 探索目标 {g}", en: "{m} modules · {f} features · {r} rules · {g} targets", ja: "{m} モジュール · {f} 機能 · {r} ルール · {g} ターゲット" },
  "rulePack.usedBy": { zh: "{n} 次运行按这一版跑过 · 不可删", en: "used by {n} run(s) · cannot be deleted", ja: "{n} 回の実行で使用 · 削除不可" },
