  "exploration.currentUrl": { zh: "当前 URL（允许参数变化）", en: "Current URL (query changes allowed)", ja: "現在の URL（クエリ変更可）" },
  "exploration.rules": { zh: "按规则包范围探索", en: "Rule pack scope", ja: "ルールパックの範囲" },
  "exploration.hint": { zh: "当前 URL 保持域名与路径不变，允许 symbol 等查询参数变化；弹窗、Tab、下拉状态仍会探索。不限制屏数时仍可取消，并在无进展时停止。", en: "Current URL keeps the origin and path; query parameters such as symbol may change. Dialogs, tabs and menus remain in scope. Unlimited screens still supports cancellation and stops on no progress.", ja: "ドメインとパスを維持し、クエリ変更を許可します。画面数無制限でも取消・進展なし停止は有効です。" },
  "exploration.graphHelp": {"zh": "S 编号表示界面状态，下一行是实际路由；点击状态或连线查看该次操作的差异。虚线表示仅发现链接、未实际走过。", "en": "S numbers identify states; the next line is the route. Select a state or edge for action differences. Dashed edges are unvisited links.", "ja": "S numbers identify states; the next line is the route. Select a state or edge for action differences. Dashed edges are unvisited links."},
  "exploration.added": {"zh": "新增控件", "en": "Added controls", "ja": "Added controls"},
