  "exploration.sameState": {"zh": "采集器将操作前后合并为同一状态；下面的文字或控件仍可能发生变化。", "en": "The collector merged both observations into one state; text or controls may still differ.", "ja": "The collector merged both observations into one state; text or controls may still differ."},
  "exploration.failed": {"zh": "操作未完成", "en": "Action failed", "ja": "Action failed"},
