  // 接入：一条定长六项的清单。人要的是「还差几条」和「先修哪一条」，不是一个健康度分数。
  "surface.onboard": { zh: "接入", en: "Set up", ja: "セットアップ" },
  // 被测对象：三处静默失败——地址可空、query 导出后不带走、三条登录路只有一条能带走。
  "sut.noEnv": {
    zh: "这个项目还没有环境。先在设置里建一个。",
    en: "This project has no environment yet.",
    ja: "この プロジェクトにはまだ環境がありません。",
  },
  "sut.baseUrl": { zh: "地址（必填）", en: "Base URL (required)", ja: "アドレス（必須）" },
  "sut.baseUrlRequired": {
    zh: "地址不能为空。",
    en: "Base URL cannot be empty.",
    ja: "アドレスは必須です。",
  },
  "sut.baseUrlWhy": {
    zh: "它是抓登录态的唯一目标地址，也是导出的 playwright.config 里 baseURL 的唯一来源。留空不会当场报错——会在二十分钟后的一次运行里，或者客户仓库的第一次 npm test 上暴露。",
    en: "It is the only target for capturing a session and the only source of the exported playwright.config baseURL. Leaving it empty fails later, not now.",
    ja: "セッション取得と書き出し設定の唯一の source です。",
  },
  "sut.viewport": {
    zh: "视口（留空 = 默认 1024×720）",
    en: "Viewport (blank = the default 1024\u00d7720)",
    ja: "ビューポート（空欄＝既定 1024\u00d7720）",
  },
  "sut.viewportWhy": {
    zh: "默认那个尺寸是为压小视觉模型的图定的。一部分真实界面在那个宽度下会整块不渲染（比如交易页的下单面板）——探索器不会报错，它只是看不见半个产品。图变大每次模型调用都更贵，所以这是每个被测对象自己的设置，不是全局的。",
    en: "the default size exists to keep the vision-model image small. Some real interfaces simply do not render whole panels at that width \u2014 the explorer does not error, it just cannot see half the product. A bigger image costs more on every model call, so this is per target, not global.",
    ja: "既定サイズは視覚モデルの画像を小さく保つためのものです。実際の画面では、その幅でパネルごと描画されないことがあります（探索側はエラーにならず、単に見えません）。画像が大きいほど毎回のモデル呼び出しが高くつくため、対象ごとの設定にしています。",
  },
  "sut.carried": { zh: "随请求带上什么", en: "Carried with each request", ja: "リクエストに付与するもの" },
  "sut.carriedWhy": {
    zh: "三张长得一模一样的表，命运完全不同。这里合成一张，多一列「去向」——没真正实现的去向标红，而不是让人事后在客户仓库里发现。",
    en: "Three identical-looking tables with different fates. Merged here with a “destination” column; the one that is not actually implemented is marked red.",
    ja: "同じ見た目の 3 つの表は行き先が違います。",
  },
