  "onboard.item.model": { zh: "模型", en: "Model", ja: "モデル" },
  "onboard.item.runtime": { zh: "运行时", en: "Runtime", ja: "ランタイム" },
  "onboard.item.planner": { zh: "规划", en: "Planner", ja: "プランナー" },
  "onboard.item.guard": { zh: "执行守卫", en: "Execution guard", ja: "実行ガード" },
  "onboard.item.budget": { zh: "本次上限", en: "Budget", ja: "上限" },
  "onboard.why.project": {
    zh: "项目是这一切挂靠的对象：用例、环境、运行记录都属于某个项目。没有它，复核队列没有内容可读。",
    en: "Everything hangs off a project: cases, environments, runs. Without one the review queue has nothing to show.",
    ja: "すべてはプロジェクトに紐づきます。",
  },
  "onboard.why.sut": {
    zh: "地址是抓登录态的唯一目标，也是导出 playwright.config 里 baseURL 的唯一来源。它为空时不会当场报错——会在二十分钟后的一次运行里，或者客户仓库的第一次 npm test 上暴露。",
    en: "The base URL is the only target for capturing a session and the only source of the exported playwright.config baseURL. Empty, it fails twenty minutes later — or in the customer's repo.",
    ja: "baseURL はセッション取得と書き出し設定の唯一の source です。",
  },
  "onboard.why.model": {
    zh: "「配了端点」和「它真的通」是两件事。绿色只给验证过的——一个从没验证过的端点会让一整场运行失败，而失败信息读起来像模型服务坏了。",
    en: "Configured is not verified. Green is reserved for what has actually answered.",
    ja: "設定済みと検証済みは別物です。",
  },
  "onboard.why.runtime": {
    zh: "绿色只留给健康检查通过。`spawning` 不算就绪——就绪超时只写 lastError 不改状态，于是一个健康检查从没通过的服务看起来是健康的。",
    en: "Green is only for a passed health check. `spawning` is not ready — the readiness timeout writes lastError without changing state.",
    ja: "緑はヘルスチェック通過のみ。",
  },
  "onboard.why.planner": {"zh": "Web 发起生成时，写故事和用例的是这个运行时：默认是本机的 Claude Code（TP_AGENT_RUNTIME 可改成 penguin）。这里只查它起不起得来，不查有没有登录——没登录的 Claude Code 会在运行里报错。", "en": "This runtime writes stories and cases for runs started from Web: Claude Code on this machine by default (TP_AGENT_RUNTIME=penguin to switch). Only whether it can start is checked, not whether it is signed in.", "ja": "Web から開始した実行でストーリーとケースを書くランタイム。既定はこのマシンの Claude Code。"},
  "onboard.why.guard": {
    zh: "禁止名单上的地址什么都不跑；环境没勾「允许不可逆」时，删除 / 支付 / 结账这类步骤会被一律拒绝。不在跑之前说出来，人会在执行报告里看到一堆没有理由的失败。",
    en: "Denied hosts never run; unless the environment allows irreversible steps, steps matching delete / pay / checkout are refused — say it before the run, not in the report.",
    ja: "拒否リストのホストは実行されません。環境が不可逆操作を許可していない場合、削除・支払い等の手順は拒否されます。",
  },
  "onboard.why.budget": {
    zh: "上限是事先的决定，不是撞墙之后才发现的一堵墙。每次起跑可以单独覆盖它。",
    en: "A cap is a decision made in advance, not a wall discovered on impact. Each run can override it.",
    ja: "上限は事前の決定です。実行ごとに上書きできます。",
  },
