  "gold.scope": { zh: "这里管理仓库级基准数据集，不随左下角项目切换。当前界面不支持新建基准或添加条目。", en: "Repository benchmarks are independent of the selected project. Creating benchmarks or adding items is not supported here yet.", ja: "ここではプロジェクトと独立した基準データを管理します。新規基準・項目の追加は未対応です。" },
  "gold.frozenHelp": { zh: "当前数据集已冻结，编辑和保存被锁定。查看是可用的；修改必须由人工决定开启新谱系，旧结果不能当成新基线。", en: "This dataset is frozen and read-only. A human must start a new lineage before editing; old results do not establish its new baseline.", ja: "凍結済みのため閲覧のみ可能です。編集には人が新しい系譜を開始する必要があります。" },
  "gold.draftHelp": { zh: "先由人工核对预期、出处和屏幕判据，再划分开发与留出条目并保存。冻结前必须具备留出项；agent 不代替人工复核。", en: "Review expectations, sources and screen-based verdicts, split development and held-out items, then save. Freezing requires held-out items. An agent cannot perform human review.", ja: "期待値・根拠・画面の判定を人が確認し、開発用と留保用に分割して保存します。エージェントは人の承認を代行しません。" },
  "gold.needSave": { zh: "尚无正式 gold.json：需要先保存复核结果。", en: "No gold.json yet: save the review first.", ja: "gold.json がありません。先にレビューを保存してください。" },
  "gold.needHeldout": { zh: "尚无留出项，不能冻结。", en: "No held-out items; freezing is unavailable.", ja: "留保項目がないため凍結できません。" },
  "gold.unsaved": { zh: "有未保存的改动或确认，先保存再冻结。", en: "Unsaved changes or confirmations: save before freezing.", ja: "未保存の変更・確認があります。凍結前に保存してください。" },
  "evaldesk.openGold": { zh: "查看并人工复核对应 Gold", en: "Open the matching Gold for human review", ja: "対応する Gold を開いて確認" },
  "evaldesk.gatewayHint": { zh: "插件必须连接右上角所示的同一网关（TP_SERVER_URL）；浏览器切换网关不会更改已启动的 MCP 插件。", en: "The plugin must use the gateway shown above via TP_SERVER_URL. Changing the browser gateway does not change an already-running MCP plugin.", ja: "プラグインの TP_SERVER_URL を右上のゲートウェイに合わせてください。ブラウザの変更は起動済み MCP に反映されません。" },
  "gold.archivedToggle": { zh: "显示归档基准", en: "Show archived benchmarks", ja: "アーカイブを表示" },
  "gold.archived": { zh: "已归档，只读", en: "Archived, read-only", ja: "アーカイブ・読み取り専用" },
  "scoreboard.selectProject": { zh: "请先在左下角选择项目；旧基准成绩可切换到研究历史查看。", en: "Select a project first, or switch to research history for legacy scores.", ja: "プロジェクトを選択してください。旧スコアは研究履歴で確認できます。" },
  "scoreboard.sourceNote": { zh: "金标成绩来自明确绑定数据集的评分记录。归档成绩只作追溯，不代表当前项目质量，也不是本轮迭代结果。", en: "Gold scores come from dataset-bound scoring records. Archived scores are historical evidence, not current project quality or this iteration\u2019s results.", ja: "金標スコアはデータセットに紐づく評価結果です。アーカイブは現在の品質を示しません。" },
  "scoreboard.diagnostics": { zh: "迭代诊断记录", en: "Iteration diagnostics", ja: "反復診断" },
  "scoreboard.diagnosticNote": { zh: "诊断记录独立展示，不转换成金标分数。点击查看有效性和失败原因。", en: "Diagnostics are separate from Gold scores. Open a record for validity and failure details.", ja: "診断は金標スコアと別です。クリックして有効性・失敗原因を確認できます。" },
  "gold.createDraft": { zh: "新建项目 Gold 草稿", en: "Create project Gold draft", ja: "プロジェクト Gold 下書きを作成" },
  "gold.draftJson": { zh: "Gold 草稿 JSON", en: "Gold draft JSON", ja: "Gold 下書き JSON" },
  "gold.createHelp": { zh: "先选择项目，粘贴包含 id 和 items 的候选清单 JSON。预期、出处、规则族和数据划分需逐条人工确认；创建不会自动复核或冻结。", en: "Select a project and paste a candidate JSON with id and items. Each expectation, source, rule family and split needs human review. Creation does not approve or freeze it.", ja: "プロジェクトを選び id と items を含む候補 JSON を貼り付けます。作成しても承認・凍結されません。" },
  "gold.scopeNew": { zh: "这里只显示当前项目的 Gold；新建草稿会关联当前项目。归档数据保留原文件，只读查看。", en: "Benchmarks are listed independently. New drafts link to the selected project. Archived files remain read-only.", ja: "基準は独立して表示されます。新規下書きは選択中のプロジェクトに紐づきます。" },
  "evaldesk.registered": { zh: "比较已有宿主运行", en: "Compare existing host runs", ja: "既存ホスト実行を比較" },
  "evaldesk.registeredHelp": { zh: "选择同一项目、同一份材料生成且已定稿的两次运行，选择该项目已复核冻结的 Gold。只比较开发集覆盖；不同宿主模型的差异不能归因于运行时。", en: "Select two finalized runs from this project with identical source materials and enter its human-reviewed frozen benchmark ID. Development coverage only; different host models confound runtime attribution.", ja: "同一資料から生成した定稿済み実行を選び、承認・凍結済み基準 ID を入力します。開発用の被覆のみ比較します。" },
  "evaldesk.compareRegistered": { zh: "比较已定稿产物", en: "Compare finalized outputs", ja: "定稿済み成果物を比較" },
